use tracing_subscriber::prelude::*;
use tracing_subscriber::{EnvFilter, Registry};

use crate::config::{LogFormat, LoggingConfig};

// Generated by build.rs: `const CRATE_NAMES: &[&str]` listing all objectstore workspace crates.
include!(concat!(env!("OUT_DIR"), "/constants.gen.rs"));

/// Initializes the global tracing subscriber with structured logging.
///
/// Reads `RUST_LOG` for filter directives; falls back to `INFO`-level logging with `TRACE`-level
/// for internal objectstore crates. Log format (`pretty`, `simplified`, or `json`) is determined
/// by `config.format`, defaulting to pretty when a terminal is attached.
///
/// When built with the `sentry` feature, also attaches Sentry tracing layers if the Sentry client
/// has been initialized. `ERROR`..`DEBUG` spans become Sentry spans and `ERROR`..`DEBUG` events
/// become Sentry logs. `ERROR` and `WARN` events also become Sentry error events. Logs and error
/// events include the attributes of their parent spans. `TRACE` spans and events are ignored.
pub fn init(config: &LoggingConfig) {
    #[cfg(feature = "sentry")]
    let sentry_layer = sentry::Hub::current()
        .client()
        .filter(|c| c.is_enabled())
        .map(|_| {
            use sentry::integrations::tracing::{ErrorLayer, LogLayer, SpanLayer};
            use tracing_subscriber::filter::{FilterExt, LevelFilter, filter_fn};

            // Span attributes come only from spans that pass both the span layer's
            // and the event layer's filter, so the error layer accepts all spans.
            let error_filter = LevelFilter::WARN.or(filter_fn(|metadata| metadata.is_span()));

            SpanLayer::new()
                .with_filter(LevelFilter::DEBUG)
                .and_then(
                    ErrorLayer::new()
                        .enable_span_attributes()
                        .with_filter(error_filter),
                )
                .and_then(
                    LogLayer::new()
                        .enable_span_attributes()
                        .with_filter(LevelFilter::DEBUG),
                )
        });

    let format = tracing_subscriber::fmt::layer()
        .with_writer(std::io::stderr)
        .with_target(true);

    let format: Box<dyn tracing_subscriber::Layer<Registry> + Send + Sync> =
        match (config.format, console::user_attended()) {
            (LogFormat::Auto, true) | (LogFormat::Pretty, _) => {
                format.compact().without_time().boxed()
            }
            (LogFormat::Auto, false) | (LogFormat::Simplified, _) => {
                format.with_ansi(false).boxed()
            }
            (LogFormat::Json, _) => format
                .json()
                .flatten_event(true)
                .with_current_span(true)
                .with_span_list(true)
                .with_file(true)
                .with_line_number(true)
                .boxed(),
        };

    let env_filter = match EnvFilter::try_from_default_env() {
        Ok(filter) => filter,
        Err(_) => default_filter(),
    };

    #[cfg(not(feature = "sentry"))]
    tracing_subscriber::registry()
        .with(format.with_filter(config.level))
        .with(env_filter)
        .init();

    #[cfg(feature = "sentry")]
    tracing_subscriber::registry()
        .with(format.with_filter(config.level))
        .with(sentry_layer)
        .with(env_filter)
        .init();
}

/// Builds the default [`EnvFilter`] when `RUST_LOG` is not set.
///
/// Uses `INFO` as the base level. Selected dependencies are raised to `DEBUG` where their debug
/// logs are low-volume and useful for diagnosing production issues. Every internal objectstore
/// crate discovered at build time is set to `TRACE`.
fn default_filter() -> EnvFilter {
    // Target `bigtable_rs::bigtable` rather than the whole crate: other modules log per request.
    let mut filter = EnvFilter::new("INFO,tower_http=DEBUG,bigtable_rs::bigtable=DEBUG");

    for name in CRATE_NAMES {
        // INVARIANT: crate names are valid identifiers; the directive cannot fail to parse.
        filter = filter.add_directive(format!("{name}=TRACE").parse().unwrap());
    }

    filter
}
